const rows = $input.all().map(x => x.json);
const byId = {};
for (const r of rows) {
  const id = String(r['Order Id'] || '').trim();
  if (!id) continue;
  byId[id] = r;
}
const out = [];
for (const id of Object.keys(byId)) {
  const r = byId[id];
  out.push({
    json: {
      target_order_id: id,
      gt_decision: r['decision_expected'],
      gt_policies: r['expected_policies']
    }
  });
}
return out;

// n8n Code Node — Evaluation Metrics Calculator
// Input: array of test case items from previous node
// Each item should have: order_id, tool_used, resolution_decision,
//   gt_decision, policy_citations, gt_policies, coherence_score

const items = $input.all();

// ─── helpers ───────────────────────────────────────────────────────────────

/**
 * Parse the tool_used field.
 * Accepts a JSON string like '["search_playbook","Simple_Vector_Store"]'
 * or an array already.
 */
function parseTools(raw) {
  if (Array.isArray(raw)) return raw;
  try { return JSON.parse(raw); } catch { return []; }
}

/**
 * Parse policy_citations field.
 * Accepts either:
 *   - an object  { "0": "POL-004", "1": "POL-002" }
 *   - a string   '{"0":"POL-004","1":"POL-002"}'
 *   - an array   ["POL-004", "POL-002"]
 * Returns a flat array of policy IDs.
 */
function parseCitations(raw) {
  if (!raw) return [];
  let obj = raw;
  if (typeof raw === "string") {
    try { obj = JSON.parse(raw); } catch { return []; }
  }
  if (Array.isArray(obj)) return obj.map(String);
  if (typeof obj === "object") return Object.values(obj).map(String);
  return [];
}

/**
 * Parse gt_policies field.
 * Accepts a pipe-separated string "POL-002|POL-006", a plain string "POL-004",
 * or an array.
 * Returns a flat array of policy IDs.
 */
function parseGtPolicies(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw.map(String);
  return String(raw).split("|").map(s => s.trim()).filter(Boolean);
}

// Expected tools that indicate tool usage (adjust if needed)
const EXPECTED_TOOLS = ["search_playbook", "Simple_Vector_Store"];

// ─── per-case metrics ───────────────────────────────────────────────────────

const results = items.map(item => {
  const d = item.json;

  const resolution   = String(d.resolution_decision || "").trim().toLowerCase();
  const gtDecision   = String(d.gt_decision || "").trim().toLowerCase();
  const coherence    = parseFloat(d.coherence_score) || 0;
  const tools        = parseTools(d.tool_used);
  const citations    = parseCitations(d.policy_citations);
  const gtPolicies   = parseGtPolicies(d.gt_policies);

  // 1. Decision match (1 = correct, 0 = wrong)
  const decisionMatch = resolution === gtDecision ? 1 : 0;

  // 2. Escalation accuracy
  //    Correct if BOTH resolution AND gt_decision are "escalate_human",
  //    or NEITHER is "escalate_human"
  const resEscalated = resolution === "escalate_human";
  const gtEscalated  = gtDecision  === "escalate_human";
  const escalationMatch = resEscalated === gtEscalated ? 1 : 0;

  // 3. Policy citation recall
  //    How many of the ground-truth policies were cited?
  let citationRecall = 0;
  if (gtPolicies.length > 0) {
    const hits = gtPolicies.filter(p => citations.includes(p)).length;
    citationRecall = hits / gtPolicies.length;
  }

  // 4. Policy exact match
  //    1 only if the cited set exactly equals the gt set (order-insensitive)
  const exactMatch =
    gtPolicies.length === citations.length &&
    gtPolicies.every(p => citations.includes(p)) &&
    citations.every(p => gtPolicies.includes(p))
      ? 1 : 0;

  // 5. Task completion
  //    1 if a resolution_decision was produced and is non-empty
  const taskComplete = resolution.length > 0 ? 1 : 0;

  // 6. Tool accuracy
  //    1 if AT LEAST ONE expected tool was used
  const toolAccuracy = EXPECTED_TOOLS.some(t => tools.includes(t)) ? 1 : 0;

  return {
    order_id:         d.order_id,
    decisionMatch,
    escalationMatch,
    citationRecall,
    exactMatch,
    coherence,        // already on 0–1 scale; multiply ×5 below for 1–5
    taskComplete,
    toolAccuracy,
  };
});

// ─── aggregate metrics ──────────────────────────────────────────────────────

const n = results.length;

function pct(arr, key) {
  return n === 0 ? 0 : (arr.reduce((s, r) => s + r[key], 0) / n) * 100;
}

function avg(arr, key) {
  return n === 0 ? 0 : arr.reduce((s, r) => s + r[key], 0) / n;
}

const metrics = {
  // Percentage of cases where resolution_decision === gt_decision
  decision_accuracy_pct: parseFloat(pct(results, "decisionMatch").toFixed(2)),

  // Percentage of cases where escalation status matches
  escalation_accuracy_pct: parseFloat(pct(results, "escalationMatch").toFixed(2)),

  // Average % of ground-truth policies that appear in citations
  policy_citation_recall_pct: parseFloat((avg(results, "citationRecall") * 100).toFixed(2)),

  // Percentage of cases with exactly-matching policy sets
  policy_exact_match_pct: parseFloat(pct(results, "exactMatch").toFixed(2)),

  // Mean coherence score scaled to 1–5
  mean_coherence_1to5: parseFloat((avg(results, "coherence") * 5).toFixed(3)),

  // Percentage of cases where a decision was produced
  task_completion: parseFloat(pct(results, "taskComplete").toFixed(2)),

  // Percentage of cases where at least one expected tool was used
  tool_accuracy: parseFloat(pct(results, "toolAccuracy").toFixed(2)),

  // Meta
  total_cases: n,
};

// ─── output ─────────────────────────────────────────────────────────────────
// Returns one item with the aggregated metrics
// (plus per-case breakdown in case_results for debugging)

return [
  {
    json: {
      ...metrics,
      case_results: results,
    },
  },
];
